SourceCode.Declaration:
/// <summary>
/// Builds the Mobile item snapshot of the company it runs in - nightly, and on "Rebuild snapshot
/// now". The files are the getSkuPage feeds of a full refresh, ZIP (one .jsonl entry), one page of rows per line.
/// In batch the build is split into tasks by key range (HSMobileOpsSkuSnapshotTask) that run side by
/// side on the batch threads; the last one to end completes the build. Outside batch it runs in turn.
/// A deploy or restart ends the batch job part way: the next build marks a Building snapshot whose
/// job no longer runs as Failed (interrupted) and removes its files, so it never blocks a rebuild.
///
/// Stores that sync by assortment (Mobile warehouse control) get a snapshot of their own, of their
/// item list only. The company's tasks are queued first and the stores' item lists refreshed
/// meanwhile; once the company snapshot is Ready, each store's is cut from its files
/// (HSMobileOpsSkuStoreFilter) - no queries or unit conversions again. Stores with the same
/// assortment share one cut: it is made once and copied. A store's devices page through the
/// store's items until its snapshot is Ready - they never wait for the build.
/// </summary>
class HSMobileOpsSkuSnapshotBuild extends RunBaseBatch
{
    #define.CurrentVersion(1)
}

Method.Source:
/// <summary>
/// Rebuild snapshot now: a one-off batch job for this company (a 1M-item build runs about an
/// hour), plus the nightly job if this company has none.
/// </summary>
public static void main(Args _args)
{
    BatchHeader batchHeader;
    boolean     scheduled = HSMobileOpsSkuSnapshotBuild::ensureScheduled();

    batchHeader = BatchHeader::construct();
    batchHeader.parmCaption(HSMobileOpsSkuSnapshotBuild::caption() + ' (now)');
    batchHeader.addTask(new HSMobileOpsSkuSnapshotBuild());
    batchHeader.save();
    info(strFmt('Snapshot build for %1 started as a batch job. It shows here as Building, then Ready.', curExt()));
    if (scheduled)
    {
        info(strFmt('Batch job "%1" scheduled: nightly at 01:00 UTC.', HSMobileOpsSkuSnapshotBuild::caption()));
    }
    if (_args && _args.record() && _args.record().isFormDataSource())
    {
        FormDataUtil::getFormDataSource(_args.record()).research(true);
    }
}

/// <summary>
/// One build for the current company. The new snapshot becomes the current one only once all
/// its files are written; the older ones and their files are removed afterwards.
/// </summary>
public static str build()
{
    HSMobileOpsSkuSnapshot company;
    utcdatetime            started = DateTimeUtil::utcNow();
    str                    result;

    if (HSMobileOpsSkuSnapshotBuild::isBuilding(DateTimeUtil::utcNow()))
    {
        return 'Another snapshot build of this company is still running - not started.';
    }
    result = HSMobileOpsSkuSnapshotBuild::buildScope('');
    HSMobileOpsSkuSnapshotBuild::refreshScopes();
    company = HSMobileOpsSkuSnapshot::current('');
    if (company.RecId && company.BuiltAtUtc >= started)
    {
        result += HSMobileOpsSkuSnapshotBuild::startStoreSnapshots(company.RecId, null);
    }
    return result;
}

/// <summary>
/// One snapshot, written in turn: '' every item, a warehouse its store's item list.
/// </summary>
private static str buildScope(InventLocationId _scope)
{
    HSMobileOpsSkuSnapshot snapshot;
    utcdatetime            started = DateTimeUtil::utcNow();
    str                    result;
    str                    failure;
    int64                  items;
    int64                  barcodes;
    int64                  variants;
    int64                  units;

    ttsbegin;
    snapshot.BuiltAtUtc = started;
    snapshot.Status     = HSMobileOpsSkuSnapshot::statusBuilding();
    snapshot.Scope      = _scope;
    snapshot.insert();
    ttscommit;

    try
    {
        items    = HSMobileOpsSkuSnapshotBuild::writeArea(snapshot.RecId, 'ITEMS', '', '', 0, _scope);
        barcodes = HSMobileOpsSkuSnapshotBuild::writeArea(snapshot.RecId, 'BARCODES', '', '', 0, _scope);
        variants = HSMobileOpsSkuSnapshotBuild::writeArea(snapshot.RecId, 'VARIANTS', '', '', 0, _scope);
        units    = HSMobileOpsSkuSnapshotBuild::writeArea(snapshot.RecId, 'UNITS', '', '', 0, _scope);
        result = strFmt('%1 items, %2 barcodes, %3 variants, units of %4 items.', items, barcodes, variants, units);
        HSMobileOpsSkuSnapshotBuild::finish(snapshot.RecId, HSMobileOpsSkuSnapshot::statusReady(), started, result);
        HSMobileOpsSkuSnapshotBuild::removeOlder(snapshot.RecId);
        return result;
    }
    catch (Exception::CLRError)
    {
        failure = HSMobileOpsSkuSnapshotBuild::clrFailure();
    }
    catch
    {
        failure = HSMobileOpsSkuSnapshotBuild::lastInfo();
    }
    HSMobileOpsSkuSnapshotBuild::finish(snapshot.RecId, HSMobileOpsSkuSnapshot::statusFailed(), started,
        'Failed: ' + (failure ? failure : 'see the batch job log'));
    HSMobileOpsSkuSnapshotBuild::removeSnapshot(snapshot.RecId, false);
    return 'Failed: ' + failure;
}

/// <summary>
/// Whether another build of this company started in the last 4 hours is still Building.
/// </summary>
private static boolean isBuilding(utcdatetime _now, RefRecId _currentJob = 0)
{
    HSMobileOpsSkuSnapshot snapshot;

    HSMobileOpsSkuSnapshotBuild::failInterrupted(_currentJob);
    select firstOnly RecId from snapshot
        where snapshot.Status     == HSMobileOpsSkuSnapshot::statusBuilding()
           && snapshot.BuiltAtUtc >  DateTimeUtil::addHours(_now, -4);
    return snapshot.RecId != 0;
}

/// <summary>
/// Building snapshots whose batch job is no longer running (a restart or deploy ended it part
/// way - its tasks do not run again), or of _currentJob, the job starting a new build now (a
/// recurring job keeps its record): Failed, with their files removed.
/// </summary>
internal static void failInterrupted(RefRecId _currentJob = 0)
{
    HSMobileOpsSkuSnapshot snapshot;
    BatchJob               batchJob;

    while select RecId, BatchJobId, BuiltAtUtc from snapshot
        where snapshot.Status     == HSMobileOpsSkuSnapshot::statusBuilding()
           && snapshot.BatchJobId != 0
    {
        select firstOnly RecId, Status from batchJob
            where batchJob.RecId == snapshot.BatchJobId;
        if (!batchJob.RecId || snapshot.BatchJobId == _currentJob
            || (batchJob.Status != BatchStatus::Executing && batchJob.Status != BatchStatus::Waiting
                && batchJob.Status != BatchStatus::Ready))
        {
            HSMobileOpsSkuSnapshotBuild::finish(snapshot.RecId, HSMobileOpsSkuSnapshot::statusFailed(), snapshot.BuiltAtUtc,
                'Interrupted: its batch job ended before the build finished (a restart or deploy).');
            HSMobileOpsSkuSnapshotBuild::removeSnapshot(snapshot.RecId, false);
        }
    }
}

/// <summary>
/// Tasks per large area (ITEMS, BARCODES, UNITS). The batch framework runs as many at once as
/// the batch server has threads; the rest wait their turn.
/// </summary>
private static int taskCount()
{
    return 8;
}

/// <summary>
/// The build split into tasks of this batch job: ITEMS and UNITS by item number range,
/// BARCODES by RecId range, VARIANTS in one. The snapshot row counts them; the last task to
/// end completes it (taskEnded).
/// </summary>
internal static str startTasks(Batch _current)
{
    HSMobileOpsSkuSnapshot  snapshot;
    utcdatetime             started = DateTimeUtil::utcNow();
    container               itemBounds;
    container               barcodeBounds;
    List                    tasks = new List(Types::Container);
    ListEnumerator          taskEnum;
    BatchHeader             batchHeader;
    container               task;
    int                     i;

    if (HSMobileOpsSkuSnapshotBuild::isBuilding(started, _current.BatchJobId))
    {
        return 'Another snapshot build of this company is still running - not started.';
    }
    itemBounds    = HSMobileOpsSkuSnapshotBuild::itemBoundaries();
    barcodeBounds = HSMobileOpsSkuSnapshotBuild::barcodeBoundaries();
    // [area, index, after, upTo] - the ranges (bound i-1, bound i], open at both ends.
    for (i = 1; i <= conLen(itemBounds) + 1; i++)
    {
        tasks.addEnd(['ITEMS', i,
            i > 1 ? conPeek(itemBounds, i - 1) : '',
            i <= conLen(itemBounds) ? conPeek(itemBounds, i) : '']);
    }
    for (i = 1; i <= conLen(barcodeBounds) + 1; i++)
    {
        tasks.addEnd(['BARCODES', i,
            i > 1 ? int642Str(conPeek(barcodeBounds, i - 1)) : '',
            i <= conLen(barcodeBounds) ? int642Str(conPeek(barcodeBounds, i)) : '']);
    }
    tasks.addEnd(['VARIANTS', 1, '', '']);
    for (i = 1; i <= conLen(itemBounds) + 1; i++)
    {
        tasks.addEnd(['UNITS', i,
            i > 1 ? conPeek(itemBounds, i - 1) : '',
            i <= conLen(itemBounds) ? conPeek(itemBounds, i) : '']);
    }

    ttsbegin;
    snapshot.BuiltAtUtc = started;
    snapshot.Status     = HSMobileOpsSkuSnapshot::statusBuilding();
    snapshot.TasksTotal = tasks.elements();
    snapshot.BatchJobId = _current.BatchJobId;
    snapshot.insert();
    ttscommit;

    try
    {
        batchHeader = BatchHeader::construct(_current.BatchJobId);
        taskEnum = tasks.getEnumerator();
        while (taskEnum.moveNext())
        {
            task = taskEnum.current();
            batchHeader.addRuntimeTask(HSMobileOpsSkuSnapshotTask::newTask(snapshot.RecId,
                conPeek(task, 1), conPeek(task, 2), conPeek(task, 3), conPeek(task, 4)), _current.RecId);
        }
        batchHeader.save();
    }
    catch
    {
        HSMobileOpsSkuSnapshotBuild::finish(snapshot.RecId, HSMobileOpsSkuSnapshot::statusFailed(), started,
            'Failed: the tasks could not be added - ' + HSMobileOpsSkuSnapshotBuild::lastInfo());
        return 'Failed: the tasks could not be added.';
    }
    // The company's tasks are queued and running: meanwhile the stores' item lists. The
    // stores' snapshots are cut from the company's once it is Ready (completeTasks).
    HSMobileOpsSkuSnapshotBuild::refreshScopes();
    return strFmt('Snapshot build for %1 split into %2 tasks; store item lists refreshed.', curExt(), tasks.elements());
}

/// <summary>
/// After the company snapshot is Ready: a snapshot row for each store that syncs by assortment,
/// and one task per distinct assortment (stores with the same item list share it) that cuts
/// the store's files from the company's. Outside batch (_current null) the cuts run in turn.
/// </summary>
internal static str startStoreSnapshots(RefRecId _company, Batch _current)
{
    HSMobileOpsWarehouseControl control;
    HSMobileOpsSkuSnapshot      snapshot;
    Map                         groups = new Map(Types::String, Types::Container);
    MapEnumerator               groupEnum;
    BatchHeader                 batchHeader;
    container                   members;
    container                   memberRecs;
    str                         key;
    RefRecId                    leader;
    int                         stores;
    int                         i;

    while select Warehouse, AssortmentHash from control
        order by Warehouse
        where control.SyncByAssortment == NoYes::Yes
           && control.AssortmentItems  >  0
    {
        key = control.AssortmentHash ? control.AssortmentHash : control.Warehouse;
        members = groups.exists(key) ? groups.lookup(key) : conNull();
        members += control.Warehouse;
        groups.insert(key, members);
        stores++;
    }
    if (!stores)
    {
        return '';
    }
    try
    {
        if (_current)
        {
            batchHeader = BatchHeader::construct(_current.BatchJobId);
        }
        groupEnum = groups.getEnumerator();
        while (groupEnum.moveNext())
        {
            members    = groupEnum.currentValue();
            memberRecs = conNull();
            ttsbegin;
            for (i = 1; i <= conLen(members); i++)
            {
                snapshot.clear();
                snapshot.BuiltAtUtc = DateTimeUtil::utcNow();
                snapshot.Status     = HSMobileOpsSkuSnapshot::statusBuilding();
                snapshot.Scope      = conPeek(members, i);
                snapshot.TasksTotal = 1;
                snapshot.BatchJobId = _current ? _current.BatchJobId : 0;
                snapshot.insert();
                memberRecs += snapshot.RecId;
            }
            ttscommit;
            leader = conPeek(memberRecs, 1);
            if (_current)
            {
                batchHeader.addRuntimeTask(HSMobileOpsSkuSnapshotTask::newTask(leader, 'STORE', conLen(members),
                    int642Str(_company), con2Str(conDel(memberRecs, 1, 1), ','), conPeek(members, 1)), _current.RecId);
            }
            else
            {
                HSMobileOpsSkuSnapshotBuild::buildStoreGroup(leader, _company, conDel(memberRecs, 1, 1), conPeek(members, 1));
            }
        }
        if (_current)
        {
            batchHeader.save();
        }
    }
    catch
    {
        return strFmt(' The stores\' snapshots could not be started - %1', HSMobileOpsSkuSnapshotBuild::lastInfo());
    }
    return strFmt(' %1 store snapshot(s) by assortment, %2 distinct assortment(s).', stores, groups.elements());
}

/// <summary>
/// One task: the store snapshot _leader cut from the company snapshot, then its files copied to
/// the other stores with the same assortment (_others: their snapshot rows). Each becomes Ready
/// and replaces that store's older snapshot.
/// </summary>
internal static void buildStoreGroup(RefRecId _leader, RefRecId _company, container _others, InventLocationId _scope)
{
    HSMobileOpsSkuSnapshot     leader;
    HSMobileOpsSkuSnapshotFile file;
    HSMobileOpsSkuSnapshotFile copy;
    container                  areas = HSMobileOpsSkuPageService::snapshotAreas();
    container                  rows;
    Set                        items;
    RecordInsertList           copies;
    RefRecId                   other;
    str                        result;
    str                        failure;
    int                        a;
    int                        i;

    select firstOnly BuiltAtUtc from leader where leader.RecId == _leader;
    try
    {
        items = HSMobileOpsSyncAssortItem::itemSet(_scope);
        for (a = 1; a <= conLen(areas); a++)
        {
            rows += HSMobileOpsSkuStoreFilter::filterArea(_company, _leader, conPeek(areas, a), items);
        }
        result = strFmt('%1 items, %2 barcodes, %3 variants, units of %4 items. Cut from the company snapshot%5.',
            conPeek(rows, 1), conPeek(rows, 2), conPeek(rows, 3), conPeek(rows, 4),
            conLen(_others) ? strFmt(', shared by %1 stores with the same assortment', conLen(_others) + 1) : '');
        for (i = 1; i <= conLen(_others); i++)
        {
            other  = conPeek(_others, i);
            copies = new RecordInsertList(tableNum(HSMobileOpsSkuSnapshotFile));
            while select file
                where file.SnapshotRecId == _leader
            {
                copy.data(file);
                copy.SnapshotRecId = other;
                copies.add(copy);
            }
            ttsbegin;
            copies.insertDatabase();
            ttscommit;
        }
    }
    catch (Exception::CLRError)
    {
        failure = HSMobileOpsSkuSnapshotBuild::clrFailure();
    }
    catch
    {
        failure = HSMobileOpsSkuSnapshotBuild::lastInfo();
        if (!failure)
        {
            failure = 'error';
        }
    }
    for (i = 0; i <= conLen(_others); i++)
    {
        other = i ? conPeek(_others, i) : _leader;
        if (failure)
        {
            HSMobileOpsSkuSnapshotBuild::finish(other, HSMobileOpsSkuSnapshot::statusFailed(), leader.BuiltAtUtc, 'Failed: ' + failure);
            HSMobileOpsSkuSnapshotBuild::removeSnapshot(other, false);
        }
        else
        {
            HSMobileOpsSkuSnapshotBuild::finish(other, HSMobileOpsSkuSnapshot::statusReady(), leader.BuiltAtUtc, result);
            HSMobileOpsSkuSnapshotBuild::removeOlder(other);
        }
    }
}

/// <summary>
/// Refreshes the item list of each warehouse that syncs by assortment and answers the ones with
/// items - each gets a snapshot. Snapshots of stores that no longer sync by assortment are
/// removed. A store whose refresh fails keeps yesterday's list.
/// </summary>
internal static container refreshScopes()
{
    HSMobileOpsWarehouseControl control;
    HSMobileOpsWarehouseControl row;
    HSMobileOpsSkuSnapshot      snapshot;
    container                   scopes;
    Set                         active = new Set(Types::String);

    while select Warehouse from control
        where control.SyncByAssortment == NoYes::Yes
    {
        try
        {
            ttsbegin;
            row = HSMobileOpsWarehouseControl::find(control.Warehouse, true);
            row.refreshItems();
            row.doUpdate();
            ttscommit;
        }
        catch
        {
            row = HSMobileOpsWarehouseControl::find(control.Warehouse);
        }
        if (row.AssortmentItems > 0)
        {
            scopes += row.Warehouse;
            active.add(row.Warehouse);
        }
    }
    while select RecId, Scope from snapshot
        where snapshot.Scope  != ''
           && snapshot.Status != HSMobileOpsSkuSnapshot::statusBuilding()
    {
        if (!active.in(snapshot.Scope))
        {
            HSMobileOpsSkuSnapshotBuild::removeSnapshot(snapshot.RecId, true);
        }
    }
    return scopes;
}

/// <summary>
/// taskCount() - 1 item numbers that split the items of the ITEMS feed into equal ranges;
/// none for a small company (one task is enough).
/// </summary>
private static container itemBoundaries()
{
    const int64  MinRowsPerTask = 20000;
    InventTable  inventTable;
    container    bounds;
    int64        total;
    int64        step;
    int64        n;
    int          tasks = HSMobileOpsSkuSnapshotBuild::taskCount();

    select count(RecId) from inventTable
        where inventTable.ItemType != ItemType::Service
           && (!inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active');
    total = inventTable.RecId;
    step  = max(total div tasks + 1, MinRowsPerTask);
    if (total <= step)
    {
        return conNull();
    }
    inventTable.clear();
    while select ItemId from inventTable
        order by inventTable.ItemId
        where inventTable.ItemType != ItemType::Service
           && (!inventTable.ProductLifecycleStateId || inventTable.ProductLifecycleStateId == 'Active')
    {
        n++;
        if (n mod step == 0)
        {
            bounds += inventTable.ItemId;
            if (conLen(bounds) >= tasks - 1)
            {
                break;
            }
        }
    }
    return bounds;
}

/// <summary>
/// taskCount() - 1 RecIds that split the barcodes into equal RecId ranges; none for a few.
/// </summary>
private static container barcodeBoundaries()
{
    const int64         MinRowsPerTask = 20000;
    InventItemBarcode   barcode;
    container           bounds;
    int64               total;
    RecId               low;
    RecId               high;
    int                 tasks = HSMobileOpsSkuSnapshotBuild::taskCount();
    int                 i;

    select count(RecId) from barcode;
    total = barcode.RecId;
    if (total < 2 * MinRowsPerTask)
    {
        return conNull();
    }
    select minof(RecId) from barcode;
    low = barcode.RecId;
    select maxof(RecId) from barcode;
    high = barcode.RecId;
    for (i = 1; i < tasks; i++)
    {
        bounds += low + (high - low) * i div tasks;
    }
    return bounds;
}

/// <summary>
/// A task's end, counted on the snapshot row under a lock; the last one completes the build.
/// </summary>
internal static void taskEnded(RefRecId _snapshot, str _failure, Batch _current = null)
{
    HSMobileOpsSkuSnapshot snapshot;
    boolean                last;

    ttsbegin;
    select pessimisticLock firstOnly snapshot where snapshot.RecId == _snapshot;
    if (snapshot.RecId && snapshot.Status == HSMobileOpsSkuSnapshot::statusBuilding())
    {
        if (_failure)
        {
            snapshot.TasksFailed++;
            if (!snapshot.Result)
            {
                snapshot.Result = subStr('Failed: ' + _failure, 1, 250);
            }
        }
        else
        {
            snapshot.TasksDone++;
        }
        last = snapshot.TasksDone + snapshot.TasksFailed >= snapshot.TasksTotal;
        snapshot.update();
    }
    ttscommit;
    if (last)
    {
        HSMobileOpsSkuSnapshotBuild::completeTasks(_snapshot, _current);
    }
}

/// <summary>
/// After the last task: Failed if any task failed; otherwise each area's parts numbered
/// 1..n in key order, the snapshot Ready and the older ones removed.
/// </summary>
private static void completeTasks(RefRecId _snapshot, Batch _current)
{
    HSMobileOpsSkuSnapshot     snapshot;
    HSMobileOpsSkuSnapshotFile file;
    HSMobileOpsSkuSnapshotFile renumber;
    container                  areas = HSMobileOpsSkuPageService::snapshotAreas();
    container                  rows;
    str                        area;
    int                        a;
    int                        part;

    select firstOnly snapshot where snapshot.RecId == _snapshot;
    if (snapshot.TasksFailed)
    {
        HSMobileOpsSkuSnapshotBuild::finish(_snapshot, HSMobileOpsSkuSnapshot::statusFailed(), snapshot.BuiltAtUtc,
            snapshot.Result ? snapshot.Result : 'Failed: see the batch job log');
        HSMobileOpsSkuSnapshotBuild::removeSnapshot(_snapshot, false);
        return;
    }
    for (a = 1; a <= conLen(areas); a++)
    {
        area = conPeek(areas, a);
        part = 0;
        ttsbegin;
        while select RecId, Part from file
            order by file.Part
            where file.SnapshotRecId == _snapshot
               && file.Area          == area
        {
            part++;
            if (file.Part != part)
            {
                update_recordset renumber
                    setting Part = part
                    where renumber.RecId == file.RecId;
            }
        }
        ttscommit;
        file.clear();
        select sum(RowCount) from file
            where file.SnapshotRecId == _snapshot
               && file.Area          == area;
        rows += file.RowCount;
    }
    HSMobileOpsSkuSnapshotBuild::finish(_snapshot, HSMobileOpsSkuSnapshot::statusReady(), snapshot.BuiltAtUtc,
        strFmt('%1 items, %2 barcodes, %3 variants, units of %4 items. %5 tasks side by side.',
            conPeek(rows, 1), conPeek(rows, 2), conPeek(rows, 3), conPeek(rows, 4), snapshot.TasksTotal)
        + (snapshot.Scope ? strFmt(' Assortment of store %1.', snapshot.Scope) : ''));
    HSMobileOpsSkuSnapshotBuild::removeOlder(_snapshot);
    // The company snapshot is Ready: the stores' are cut from it now.
    if (!snapshot.Scope && _current)
    {
        info(HSMobileOpsSkuSnapshotBuild::startStoreSnapshots(_snapshot, _current));
    }
}

/// <summary>
/// The last CLR error. The reflection wrapper says only 'Exception has been thrown by the
/// target of an invocation' - the inner exception is the real one.
/// </summary>
internal static str clrFailure()
{
    System.Exception clrError = CLRInterop::getLastException();

    while (clrError && clrError.get_InnerException())
    {
        clrError = clrError.get_InnerException();
    }
    return clrError ? clrError.GetType().get_Name() + ': ' + clrError.get_Message() : 'CLR error';
}

/// <summary>
/// The whole feed of an area - each line one getSkuPage page of rows, exactly what the paged
/// sync sends - as ZIPs of one .jsonl entry, stored in HSMobileOpsSkuSnapshotFile rows.
/// A part closes at about 4 MB, so an area of a million rows becomes several parts.
/// A task writes only the keys (_after, _upTo] - '' is from the start / to the end - as parts
/// _partBase + 1, 2, ...; the build numbers them 1..n per area at the end. Returns the rows.
/// </summary>
internal static int64 writeArea(RefRecId _snapshot, str _area, str _after, str _upTo, int _partBase, InventLocationId _scope = '')
{
    const int                           PageSize = 5000;
    System.IO.MemoryStream              memory;
    System.IO.Compression.ZipArchive    zip;
    System.IO.StreamWriter              writer;
    HSMobileOpsSkuPageResponse          page;
    utcdatetime                         full = DateTimeUtil::minValue();
    int64                               partLimit = HSMobileOpsSkuSnapshotBuild::partLimitBytes();
    str                                 after = _after;
    int64                               rows;
    int64                               partRows;
    int                                 part;
    boolean                             more = true;

    while (more)
    {
        if (!memory)
        {
            part++;
            partRows = 0;
            memory = new System.IO.MemoryStream();
            zip    = new System.IO.Compression.ZipArchive(memory, System.IO.Compression.ZipArchiveMode::Create, true);
            writer = new System.IO.StreamWriter(
                zip.CreateEntry(strLwr(_area) + '.jsonl', System.IO.Compression.CompressionLevel::Optimal).Open(),
                new System.Text.UTF8Encoding(false));
        }
        page = new HSMobileOpsSkuPageResponse();
        switch (_area)
        {
            case 'ITEMS':
                HSMobileOpsSkuPageService::itemPage(page, after, full, PageSize, _upTo, _scope);
                break;
            case 'BARCODES':
                HSMobileOpsSkuPageService::barcodePage(page, str2Int64(after), full, PageSize, str2Int64(_upTo), _scope);
                break;
            case 'VARIANTS':
                HSMobileOpsSkuPageService::variantPage(page, str2Int64(after), PageSize, _scope);
                break;
            case 'UNITS':
                HSMobileOpsSkuPageService::unitPage(page, after, full, PageSize, _upTo, _scope);
                break;
            default:
                throw error(strFmt('Unknown snapshot area %1', _area));
        }
        if (page.parmRowCount() > 0)
        {
            writer.Write(page.parmRowsJson());
            writer.Write("\n");
            writer.Flush();
        }
        rows     += page.parmRowCount();
        partRows += page.parmRowCount();
        after = page.parmNextKey();
        more  = page.parmHasMore();
        // The compressed bytes so far; deflate holds back little, so 80% leaves room for it.
        if (!more || memory.get_Length() >= partLimit)
        {
            writer.Dispose();
            zip.Dispose();
            HSMobileOpsSkuSnapshotBuild::attachPart(_snapshot, _area, _partBase + part, partRows, memory);
            memory = null;
        }
    }
    return rows;
}

/// <summary>
/// Stores one part in its HSMobileOpsSkuSnapshotFile row (14 Nov: attachments failed from
/// batch on the dev VM - "clientSecret cannot be null" - and are limited by file type and
/// size per company; a row needs neither). Devices read it with getSkuSnapshotPart.
/// </summary>
internal static void attachPart(RefRecId _snapshot, str _area, int _part, int64 _rows, System.IO.MemoryStream _memory)
{
    System.Security.Cryptography.SHA256 sha = System.Security.Cryptography.SHA256::Create();
    HSMobileOpsSkuSnapshotFile          file;

    _memory.set_Position(0);
    file.Sha256 = strLwr(strReplace(System.BitConverter::ToString(sha.ComputeHash(_memory)), '-', ''));
    _memory.set_Position(0);
    ttsbegin;
    file.SnapshotRecId = _snapshot;
    file.Area          = _area;
    file.Part          = _part;
    file.RowCount      = _rows;
    file.Bytes         = _memory.get_Length();
    file.Data          = Binary::constructFromMemoryStream(_memory).getContainer();
    file.insert();
    ttscommit;
    _memory.Dispose();
}

/// <summary>
/// A part closes at about 4 MB of ZIP - one getSkuSnapshotPart answer stays a few MB.
/// </summary>
internal static int64 partLimitBytes()
{
    return 4 * 1024 * 1024;
}

internal static void finish(RefRecId _snapshot, str _status, utcdatetime _started, str _result)
{
    HSMobileOpsSkuSnapshot snapshot;

    ttsbegin;
    select forUpdate firstOnly snapshot where snapshot.RecId == _snapshot;
    if (snapshot.RecId)
    {
        snapshot.Status       = _status;
        snapshot.BuildSeconds = any2Int(DateTimeUtil::getDifference(DateTimeUtil::utcNow(), _started));
        snapshot.Result       = subStr(_result, 1, 250);
        snapshot.update();
    }
    ttscommit;
}

/// <summary>
/// Every other snapshot of the company for the same items (scope) that is not still building,
/// with its files. Other stores' snapshots are kept.
/// </summary>
internal static void removeOlder(RefRecId _keep)
{
    HSMobileOpsSkuSnapshot snapshot;
    HSMobileOpsSkuSnapshot kept;

    select firstOnly Scope from kept where kept.RecId == _keep;
    while select RecId from snapshot
        where snapshot.RecId  != _keep
           && snapshot.Scope  == kept.Scope
           && snapshot.Status != HSMobileOpsSkuSnapshot::statusBuilding()
    {
        HSMobileOpsSkuSnapshotBuild::removeSnapshot(snapshot.RecId, true);
    }
}

/// <summary>
/// A snapshot's parts; the snapshot row too when _row (a failed build keeps its row, with
/// the reason).
/// </summary>
internal static void removeSnapshot(RefRecId _snapshot, boolean _row)
{
    HSMobileOpsSkuSnapshot     snapshot;
    HSMobileOpsSkuSnapshotFile file;

    ttsbegin;
    delete_from file where file.SnapshotRecId == _snapshot;
    if (_row)
    {
        delete_from snapshot where snapshot.RecId == _snapshot;
    }
    ttscommit;
}

internal static str lastInfo()
{
    int line = infologLine();

    return line ? infolog.text(line) : '';
}

public static str caption()
{
    return 'Mobile ops: item snapshot';
}

/// <summary>
/// Whether this company has the nightly snapshot job (its caption; the one-off jobs end in "(now)") that is not finished or cancelled.
/// </summary>
public static boolean isScheduled()
{
    Batch    batch;
    BatchJob batchJob;

    select firstOnly RecId from batch
        where batch.ClassNumber == classNum(HSMobileOpsSkuSnapshotBuild)
           && batch.Company     == curExt()
        exists join batchJob
            where batchJob.RecId          == batch.BatchJobId
               && batchJob.Status         != BatchStatus::Canceled
               && batchJob.Status         != BatchStatus::Finished
               && batchJob.Caption        == HSMobileOpsSkuSnapshotBuild::caption();

    return batch.RecId != 0;
}

/// <summary>
/// The nightly job for this company - from tonight 01:00 UTC, no end - unless one exists.
/// True when this call created it.
/// </summary>
public static boolean ensureScheduled()
{
    BatchHeader       batchHeader;
    SysRecurrenceData recurrence;

    if (HSMobileOpsSkuSnapshotBuild::isScheduled())
    {
        return false;
    }
    recurrence = SysRecurrence::defaultRecurrence();
    recurrence = SysRecurrence::setRecurrenceStartDateTime(recurrence,
        DateTimeUtil::newDateTime(DateTimeUtil::date(DateTimeUtil::utcNow()) + 1, 3600));
    recurrence = SysRecurrence::setRecurrenceNoEnd(recurrence);
    recurrence = SysRecurrence::setRecurrenceUnit(recurrence, SysRecurrenceUnit::Day, 1);

    batchHeader = BatchHeader::construct();
    batchHeader.parmCaption(HSMobileOpsSkuSnapshotBuild::caption());
    batchHeader.parmRecurrenceData(recurrence);
    batchHeader.addTask(new HSMobileOpsSkuSnapshotBuild());
    batchHeader.save();
    return true;
}

public void run()
{
    if (this.isInBatch())
    {
        info(HSMobileOpsSkuSnapshotBuild::startTasks(this.parmCurrentBatch()));
    }
    else
    {
        info(HSMobileOpsSkuSnapshotBuild::build());
    }
}

